    const formData = new FormData()

    this.formTargets.forEach(form => {
      const hiddenFields = form.querySelectorAll('input[type="hidden"]:not([disabled])[name]')
      hiddenFields.forEach(field => {
        formData.append(field.name, field.value)
      })
    })

    return formData
